insert into public.content_items(slug,kind,status,title_en,title_ml,summary_en,summary_ml,body_en,body_ml,category_en,category_ml,audience,event_date,location_en,location_ml,featured,display_order) values
('first-roots-founder-circle','program','published','First Roots Founder Circle','ഫസ്റ്റ് റൂട്ട്സ് ഫൗണ്ടർ സർക്കിൾ','A six-week peer circle for early founders moving from insight to a tested proposition.','ആശയത്തിൽ നിന്ന് പരീക്ഷിച്ച മൂല്യനിർദ്ദേശത്തിലേക്ക് നീങ്ങുന്ന ആദ്യഘട്ട സ്ഥാപകർക്കുള്ള ആറാഴ്ചത്തെ കൂട്ടായ്മ.','Small cohorts meet practitioners, test assumptions and leave with a focused ninety-day plan.','ചെറിയ ഗ്രൂപ്പുകൾ വിദഗ്ധരെ കാണുകയും ധാരണകൾ പരീക്ഷിക്കുകയും വ്യക്തമായ പദ്ധതിയോടെ മുന്നോട്ട് പോകുകയും ചെയ്യും.','Founder development','സ്ഥാപക വികസനം',array['founder','mentor'],null,'Kochi + online','കൊച്ചി + ഓൺലൈൻ',true,10),
('kerala-builders-assembly','event','published','Kerala Builders Assembly','കേരള ബിൽഡേഴ്സ് അസംബ്ലി','A working gathering for founders, investors and ecosystem stewards.','സ്ഥാപകർ, നിക്ഷേപകർ, ആവാസവ്യവസ്ഥാ പ്രവർത്തകർ എന്നിവർക്കുള്ള പ്രവർത്തന സംഗമം.','A day of useful introductions and public problem-solving.','ഉപകാരപ്രദമായ പരിചയപ്പെടുത്തലുകളും പൊതുപ്രശ്ന പരിഹാരവും നിറഞ്ഞ ദിവസം.','Community gathering','സമൂഹ സംഗമം',array['founder','investor','mentor','institution','partner'],'2027-01-23','Thiruvananthapuram','തിരുവനന്തപുരം',true,30),
('beyond-the-pitch','story','published','Beyond the pitch: building for trust','പിച്ചിനപ്പുറം: വിശ്വാസത്തിനായി നിർമ്മിക്കുക','Why durable ecosystems grow through repeated, useful exchanges.','ആവർത്തിച്ചുള്ള ഉപകാരപ്രദമായ കൈമാറ്റങ്ങളിലൂടെ സ്ഥായിയായ ആവാസവ്യവസ്ഥകൾ വളരുന്നു.','Trust compounds when people show their work, share context and follow through.','പ്രവർത്തനം തുറന്ന് കാണിക്കുകയും പശ്ചാത്തലം പങ്കിടുകയും വാഗ്ദാനം പാലിക്കുകയും ചെയ്യുമ്പോൾ വിശ്വാസം വളരുന്നു.','Field note','ഫീൽഡ് നോട്ട്',array['founder','investor','mentor'],'2026-09-14',null,null,false,40),
('campus-to-company','program','published','Campus to Company','ക്യാമ്പസിൽ നിന്ന് കമ്പനിയിലേക്ക്','A practical bridge from student project to responsible venture.','വിദ്യാർത്ഥി പ്രോജക്റ്റിൽ നിന്ന് ഉത്തരവാദിത്ത സംരംഭത്തിലേക്കുള്ള പ്രായോഗിക പാലം.','Institutions nominate teams for customer discovery and incorporation readiness.','ഉപഭോക്തൃ പഠനത്തിനും കമ്പനി രൂപീകരണ സന്നദ്ധതയ്ക്കുമായി സ്ഥാപനങ്ങൾ ടീമുകളെ നാമനിർദേശം ചെയ്യുന്നു.','Student entrepreneurship','വിദ്യാർത്ഥി സംരംഭകത്വം',array['founder','institution','mentor'],null,'Across Kerala','കേരളത്തിലുടനീളം',false,50)
